Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
#define il inline
#define RG register
#define ll long long
#define N (250005)

using namespace std;

int f[N][18],c[18],ans[18],lg,m,n,k,rhl;
int fac[N],ifac[N],inv[N],cnt[N],v[N];

il void add(int *a,int *b,RG int fg){
  for (RG int i=0;i<lg;++i){
    a[i]+=fg?b[i]:(rhl-b[i]);
    if (a[i]>=rhl) a[i]-=rhl;
  }
  return;
}

il void mul(int *a,int *b){
  memset(c,0,sizeof(c));
  for (RG int i=0;i<lg;++i){
    if (!a[i]) continue;
    for (RG int j=0;i+j<lg;++j)
      c[i+j]=(1LL*a[i]*b[j]+c[i+j])%rhl;
  }
  memcpy(a,c,sizeof(c)); return;
}

il void fpm(int *a,RG int b){
  memset(ans,0,sizeof(ans)),ans[0]=1;
  while (b){
    if (b&1) mul(ans,a);
    if (b>>=1) mul(a,a);
  }
  memcpy(a,ans,sizeof(ans)); return;
}

il int qpow(RG int a,RG int b){
  RG int ans=1;
  while (b){
    if (b&1) ans=1LL*ans*a%rhl;
    if (b>>=1) a=1LL*a*a%rhl;
  }
  return ans;
}

int main(){
#ifndef ONLINE_JUDGE
  freopen("game.in","r",stdin);
  freopen("game.out","w",stdout);
#endif
  cin>>n>>k>>rhl; if (n&1) cout<<qpow(k,n),exit(0);
  fac[0]=ifac[0]=f[0][0]=1; for (m=1;m<=n;m<<=1) ++lg;
  for (RG int i=1;i<=n;++i){
    inv[i]=i==1 ? 1 : 1LL*(rhl-rhl/i)*inv[rhl%i]%rhl;
    fac[i]=1LL*fac[i-1]*i%rhl,ifac[i]=1LL*ifac[i-1]*inv[i]%rhl;
    cnt[i]=cnt[i>>1]+(i&1),f[i][cnt[i]]=ifac[i];
  }
  v[n]=1;
  for (RG int i=n;i;--i){
    if (!v[i]) continue;
    for (RG int j=i;j;(--j)&=i) v[j]=1;
  }
  for (RG int i=1;i<m;i<<=1)
    for (RG int j=0;j<=n;++j) if (j&i) add(f[j],f[j^i],1);
  for (RG int i=0;i<=n;++i) if (v[i]) fpm(f[i],k);
  for (RG int i=1;i<m;i<<=1)
    for (RG int j=0;j<=n;++j) if (j&i) add(f[j],f[j^i],0);
  cout<<(qpow(k,n)-1LL*f[n][cnt[n]]*fac[n]%rhl+rhl)%rhl; return 0;
}

